"""Emprendimiento y Empleabilidad EPJA Media N1 y N2, módulo 3 (parte 2): OAD-09 a OAD-12 (prototipos: investigar estrategias, construir, evaluar y ajustar). Todo en papel; casos ficticios y cifras de ejemplo."""
from __future__ import annotations

from hc_common import make_build

MATERIALS = "Papel, lápiz y goma. Todo se resuelve con lo escrito en la ficha: los casos son ficticios y las cifras son de ejemplo. No se necesita calculadora, internet ni materiales especiales; para el prototipo se usan dibujos en papel."
build = make_build(MATERIALS)

O9 = "EPJA-EMEM-NM1y2-OAD-09"
O10 = "EPJA-EMEM-NM1y2-OAD-10"
O11 = "EPJA-EMEM-NM1y2-OAD-11"
O12 = "EPJA-EMEM-NM1y2-OAD-12"
PRIOR = ["Sé que una idea se puede mejorar si la pruebo antes de gastar mucho.", "He trabajado o conversado con otras personas para resolver una tarea, en cualquier ámbito de la vida."]


def K(oa, n, F, use, explain, vocab, worked, mistakes, T, ctx, sc, op, rf, ex_):
    stmt, example, crit, errors, feedback = op
    evidence = ["hoja con el trabajo escrito que muestra: " + "; ".join(crit)]
    build(oa, n, F, use=use, prior=PRIOR, explain=explain, vocab=vocab, worked=worked, mistakes=mistakes, T=T, ctx=ctx, sc=sc,
          op=(stmt, example, crit, evidence, errors, feedback), reinforce=rf, extend=ex_)


