# ====================================================== OAD-12 clase 2
F = ("Ficha 2 (caso ficticio). Frases dichas en una reunión del equipo que evalúa su prototipo de feria de trueque: "
     "F1: «Tu cartel está horrible, nunca haces nada bien». F2: «Veo que el cartel se lee mal a 3 metros; propongo agrandar las letras y probar de nuevo». "
     "F3: «No hablemos de eso, mejor sigamos como estamos». F4: «Entiendo que te costó hacerlo; ¿qué necesitarías para ajustar el tamaño de las letras?». "
     "Reunión de 30 minutos: presentar resultados, 10 minutos; conversar ajustes, 15 minutos; acuerdos, 5 minutos.")
K(O12, 2, F,
  "Hoy practicaré cómo conversar con respeto sobre un prototipo: dar y recibir opiniones, escuchar y llegar a acuerdos de ajuste.",
  ["Un diálogo constructivo busca mejorar el prototipo sin dañar a las personas. Para eso se habla del hecho y no de la persona: «el cartel se lee mal a 3 metros» en vez de «eres malo para los carteles». Se propone un cambio posible y se pregunta qué ayuda se necesita.",
   "La actitud comprensiva se nota al escuchar sin interrumpir, reconocer el esfuerzo («entiendo que te costó») y preguntar antes de suponer. Quien recibe una crítica puede pedir ejemplos, agradecer lo útil y explicar su punto de vista. Nadie queda humillado ni calla por miedo.",
   "Una forma sencilla de formular una crítica útil es: hecho observado, efecto y propuesta. Después el equipo comparte la decisión: se anota el ajuste, quién lo hará y cuándo. Así la conversación termina con una acción, no con una discusión."],
  [("diálogo constructivo", "conversación respetuosa que busca mejorar algo"), ("actitud comprensiva", "escuchar y tratar de entender el punto de vista de otra persona"), ("retroalimentación", "comentario sobre un trabajo para ayudar a mejorarlo"), ("hecho observado", "dato concreto que se puede comprobar")],
  [("Reformular una crítica", "«Siempre llegas tarde» puede cambiar a una crítica constructiva. ¿Cómo?",
    ["Se describe el hecho concreto sin acusar.", "«Hoy llegaste 15 minutos tarde y nos atrasamos; ¿podemos acordar una hora de llegada?»."], "«Hoy llegaste 15 minutos tarde...; ¿acordamos una hora?»"),
   ("Usar hecho, efecto y propuesta", "El precio no se lee a 3 metros. ¿Cómo se dice con hecho, efecto y propuesta?",
    ["Hecho: el precio no se lee a 3 metros.", "Efecto: la gente no compra. Propuesta: agrandar las letras."], "«No se lee a 3 metros, se pierden ventas; propongo agrandar las letras»")],
  [("Criticar a la persona («eres malo en esto») y no al trabajo.", "La persona se defiende o calla y no se avanza.", "Hablar del hecho y proponer un ajuste."),
   ("Cortar la conversación para evitar incomodidad.", "El problema sigue sin resolverse.", "Hablar con respeto y cerrar con un acuerdo.")],
  [("abc", "{F} ¿Cuál frase es una retroalimentación constructiva y comprensiva?", "F4", "F1", "F3", "F4 reconoce el esfuerzo y ofrece ayuda para ajustar el tamaño."),
   ("abc", "{F} ¿Cuál frase critica a la persona y no al trabajo?", "F1", "F2", "F4", "F1 dice «nunca haces nada bien», que ataca a la persona."),
   ("abc", "{F} ¿Cuál frase evita hablar del problema?", "F3", "F2", "F4", "F3 corta la conversación y no busca mejorar."),
   ("abc", "{F} ¿Qué estructura usa F2?", "Hecho, efecto y propuesta", "Solo una queja", "Solo una orden", "Describe el hecho del cartel y propone una solución."),
   ("=", "{F} ¿Cuántos minutos duran las tres partes de la reunión?", "10+15+5", "Se suman los minutos de cada parte.", " minutos"),
   ("ab", "Para recibir una crítica de forma constructiva conviene", "escuchar, pedir ejemplos y agradecer lo útil", "defenderse de inmediato", "Escuchar y preguntar ayuda a entender y mejorar."),
   ("abc", "Alguien te dice que un ajuste no sirve. ¿Cuál es una buena respuesta?", "«¿Puedes darme un ejemplo de por qué?»", "«Tú no sabes nada»", "No decir nada nunca más", "Pedir un ejemplo abre el diálogo."),
   ("abc", "Una persona critica el prototipo con voz fuerte y otra se queda callada, incómoda. ¿Qué puede hacer quien coordina?", "Dar turno a la persona callada y cuidar el respeto", "Terminar la reunión", "Dar la razón a quien grita", "Asegura que se escuchen todas las voces."),
   ("ab", "Cerrar la conversación con un acuerdo significa", "anotar el ajuste, quién lo hará y cuándo", "decir que se verá después", "Un acuerdo claro convierte la conversación en acción."),
   ("abc", "En una reunión, una persona interrumpe cada vez que otra habla. ¿Qué regla ayuda?", "Un turno para cada persona", "Que hable más fuerte", "Que todos hablen a la vez", "Los turnos aseguran que cada persona sea escuchada sin interrupciones."),
   ("ab", "La actitud comprensiva se nota cuando alguien dice", "«entiendo que te costó, ¿qué necesitas para mejorarlo?»", "«no me interesa tu esfuerzo»", "Reconocer el esfuerzo y ofrecer ayuda es comprensión."),
   ("abc", "{F} Si el equipo quiere ajustar el cartel, ¿cuál es el acuerdo claro?", "«Rosa agranda las letras a 5 cm antes del jueves»", "«Ver si se puede»", "«Alguien lo hace»", "El acuerdo dice quién hace qué y para cuándo."),
   ("ab", "Si alguien se siente humillado, probablemente", "dejará de dar ideas", "dará más ideas", "La humillación hace que las personas dejen de participar y opinar.")],
  ("abc", "Un integrante dice: «Tu informe tiene errores de suma en 3 filas; podemos revisarlo juntos para corregirlos». ¿Qué características tiene?", "Hecho concreto, tono respetuoso y propuesta de ayuda", "Ataque personal", "Una orden sin explicación", "Describe el problema y propone una acción conjunta."),
  [("En Emprendimiento y Empleabilidad: ¿qué es la retroalimentación?", "Un comentario sobre un trabajo para ayudar a mejorarlo", "Sirve para ajustar el prototipo con respeto."),
   ("¿Qué incluye una crítica constructiva?", "Hecho observado, efecto y propuesta", "Con esos tres elementos la crítica sirve para actuar."),
   ("¿Para qué sirve dar turnos para hablar?", "Para que todas las personas puedan ser escuchadas", "Los turnos reducen interrupciones y malentendidos.")],
  ("Con este caso: un equipo ficticio evalúa su prototipo de reparto de pan. Hay tres comentarios mal formulados: (1) «Eres lento en las entregas», (2) «El menú es un desastre», (3) «Nadie escucha mi idea». Reescríbelos en forma constructiva con hecho, efecto y propuesta, o con una pregunta.",
   "(1) «Hoy las entregas demoraron 20 minutos más; los vecinos esperaron; ¿podemos revisar el recorrido?». (2) «En el menú faltan precios; los clientes no sabían cuánto pagar; propongo agregarlos». (3) «Me gustaría explicar mi idea; ¿tengo 2 minutos?».",
   ["los tres comentarios son reescritos", "hablan del hecho y no de la persona", "incluyen una propuesta o pregunta"],
   ["seguir atacando a la persona", "reescribir sin propuesta"],
   "Revisa que cada frase tenga hecho y propuesta. Pregunta: «¿cómo se sentiría quien la recibe?»."),
  "Reescribe «tu cartel es feo» como una crítica constructiva.",
  "Escribe un diálogo de cuatro líneas en que una persona recibe una crítica y responde con respeto.")

# ====================================================== OAD-12 clase 3
F = ("Ficha 3 (caso ficticio; tiempos y cifras de ejemplo). Tras evaluar su prototipo de reparto de almuerzos, un equipo de 3 personas acuerda tres ajustes: "
     "Ajuste 1: letras más grandes en el menú, 1 hora, responsable Lía. Ajuste 2: acordar horarios con la proveedora, 2 horas, responsable Marco. Ajuste 3: segundo ensayo con 6 vecinos, 3 horas, responsable Nico. "
     "Plazo: 5 días. Cada persona dispone de 3 horas semanales para estos ajustes. Aviso de ejemplo para sumar ayuda: «Se necesita ayudante, mujer joven, buena presencia».")
K(O12, 3, F,
  "Hoy aplicaré todo lo aprendido para convertir la evaluación en un plan de ajustes con responsables, plazos y liderazgo.",
  ["Un plan de ajustes organiza lo que se cambiará: qué ajuste, quién lo hace, cuánto tiempo toma y para cuándo. Si las horas disponibles alcanzan, se asigna a cada persona; si no, se prioriza o se pide ayuda. Un plan escrito evita olvidos y malentendidos.",
   "El liderazgo aparece en cómo se conduce este proceso: se escucha a todas las personas, se reparte según capacidades, se revisa el avance y se reconoce lo logrado. La competencia laboral también incluye pedir ayuda a tiempo y avisar cuando algo cambia, con honestidad.",
   "Al sumar personas al equipo se cuida la igualdad: un aviso debe describir las capacidades que pide la tarea y no excluir por género, edad u otra característica. Ante dudas sobre qué se permite en un aviso, se consulta la norma vigente en la institución competente."],
  [("plan de ajustes", "lista de cambios con responsable, tiempo y fecha"), ("seguimiento", "revisión periódica del avance de una tarea"), ("liderazgo", "capacidad de orientar al grupo escuchando y repartiendo tareas"), ("criterio de selección", "característica que se pide a quien postula; debe estar relacionada con la tarea")],
  [("Sumar horas", "Tres ajustes toman 2, 1 y 3 horas. ¿Cuántas horas necesita el plan?",
    ["Se suman las horas de cada ajuste.", "2 + 1 + 3 = 6."], "6 horas"),
   ("Seguir el avance", "Una persona debía terminar su ajuste el jueves y el miércoles ve que va atrasada. ¿Qué hace?",
    ["Avisa de inmediato al equipo.", "Entre todos reasignan horas o piden ayuda."], "Avisar al equipo y ajustar el plan")],
  [("Dejar el plan en la memoria de una persona.", "Si falta esa persona, nadie sabe qué hacer.", "Escribir el plan y compartirlo."),
   ("Escribir criterios de selección sobre el género o la edad.", "Esos criterios excluyen sin medir la capacidad para la tarea.", "Pedir competencias relacionadas con las funciones del cargo.")],
  [("=", "{F} ¿Cuántas horas suman los tres ajustes?", "1+2+3", "Se suman las horas de cada ajuste.", " horas"),
   ("=", "{F} ¿Cuántas horas disponibles tiene el equipo entre las tres personas?", "3*3", "Cada persona dispone de 3 horas semanales.", " horas"),
   ("ab", "{F} ¿Alcanzan las horas disponibles para los tres ajustes?", "Sí, sobran 3 horas", "No, faltan 3 horas", "Hay 9 horas disponibles y el plan necesita 6."),
   ("abc", "{F} ¿Quién es responsable del segundo ensayo con vecinos?", "Nico", "Lía", "Marco", "La ficha asigna el Ajuste 3 a Nico."),
   ("abc", "{F} ¿Cuál es el ajuste que toma más horas?", "El segundo ensayo con 6 vecinos", "Las letras más grandes", "Acordar horarios", "Toma 3 horas, más que los otros dos."),
   ("abc", "{F} ¿Qué problema del aviso conviene corregir?", "Pide «mujer joven, buena presencia», que no mide capacidades", "Que pide ayudante", "Que no tiene fecha", "Excluye por género y edad sin relación con la tarea."),
   ("abc", "{F} ¿Cómo redactar mejor ese aviso?", "«Se necesita ayudante con disponibilidad de tarde y trato amable con el público»", "«Se necesita mujer joven»", "«Se prefiere hombre»", "Describe competencias de la tarea, sin sesgos."),
   ("ab", "Lía avisa que necesita una hora extra para su ajuste. Un buen liderazgo", "revisa quién puede ayudar y ajusta el plan", "reprocha el atraso", "Escuchar y reasignar mantiene la confianza y el plazo."),
   ("abc", "{F} Si Marco dispone de 3 horas y ya usó 2 en otro ajuste, ¿cuánto le queda?", "1 hora", "3 horas", "0 horas", "3 menos 2 deja 1 hora disponible."),
   ("ab", "Un seguimiento semanal sirve para", "ver qué se cumplió y qué se atrasó", "buscar culpables", "Revisar el avance permite corregir a tiempo."),
   ("abc", "{F} ¿Qué dato falta en «Ajuste 1: letras más grandes, 1 hora, responsable Lía»?", "El tamaño o la fecha de entrega", "El nombre de Lía", "El costo del almuerzo", "Un plan completo indica qué tan grandes y para cuándo."),
   ("abc", "Al final del plazo, el equipo prueba de nuevo y mejora. ¿Qué debe hacer para aprender?", "Registrar los resultados del nuevo ensayo, también los negativos", "No registrar nada", "Esconder los fallos", "Registrar con honestidad permite seguir mejorando."),
   ("ab", "Un integrante dice «yo decido todo porque soy el de más experiencia». ¿Qué falta?", "Escuchar y repartir responsabilidades", "Más autoridad", "El liderazgo se apoya en escuchar y repartir, no solo en la experiencia.")],
  ("abc", "Un equipo ficticio de 2 personas debe hacer ajustes de 2, 3 y 4 horas, y cada una dispone de 4 horas. ¿Qué decisión es razonable?", "Pedir ayuda o mover una tarea de 1 hora a otro día", "Hacer todo en 9 horas sin avisar", "No hacer nada", "Hay 8 horas disponibles frente a 9 necesarias: se reajusta."),
  [("En Emprendimiento y Empleabilidad: ¿qué es un plan de ajustes?", "Lista de cambios con responsable, tiempo y fecha", "Convierte la evaluación en acciones concretas."),
   ("¿Por qué conviene dar seguimiento?", "Para detectar atrasos y corregir a tiempo", "El seguimiento mantiene el plan bajo control."),
   ("¿Qué debe pedir un aviso de ayudante?", "Competencias relacionadas con la tarea", "Los criterios deben medir la capacidad, no el género ni la edad.")],
  ("Con estos ajustes de ejemplo para un prototipo de venta de mermeladas: A) mejorar etiquetas, 2 horas; B) comprar frascos, 1 hora; C) ensayo con 5 personas, 3 horas. Hay 2 personas con 3 horas cada una. Escribe (1) horas necesarias y disponibles, (2) quién hace cada ajuste con nombres inventados, (3) una fecha de seguimiento y (4) un aviso sin sesgos para sumar un ayudante.",
   "Necesarias: 6; disponibles: 6. Ana: A y B (3 h). Beto: C (3 h). Seguimiento: miércoles. Aviso: «Se necesita ayudante, tardes del fin de semana, experiencia en atención de público».",
   ["compara horas necesarias y disponibles", "asigna responsables y fecha", "redacta un aviso sin sesgos de género ni edad"],
   ["no controlar las horas", "aviso con criterios discriminatorios"],
   "Revisa que 2 + 1 + 3 sea 6. Pregunta: «¿qué pide el aviso y está relacionado con la tarea?»."),
  "Escribe tres ajustes de un prototipo con responsable y fecha.",
  "Escribe un aviso para una vacante de ayudante, pidiendo solo capacidades relacionadas con la tarea.")
